@app.command("/nova_pm")
def handle_nova_pm(ack, body, client):
    ack()
    client.views_open(trigger_id=body["trigger_id"], view=NOVA_PM_MODAL)


@app.view("nova_pm_modal")
def handle_nova_pm_submission(ack, body, client, view):
    ack()

    vals = view["state"]["values"]
    skill    = vals["skill_block"]["skill_select"]["selected_option"]["value"]
    context  = vals["context_block"]["context_input"]["value"] or ""
    quarter  = vals["quarter_block"]["quarter_select"]["selected_option"]["value"]
    keywords = vals["keywords_block"]["keywords_input"]["value"] or ""

    selected = [o["value"] for o in
                (vals["options_block"]["options_check"].get("selected_options") or [])]
    do_ppt        = "ppt" in selected
    do_confluence = "confluence" in selected
    parent_page   = (vals["parent_page_block"]["parent_page_input"].get("value") or "").strip()

    user_id    = body["user"]["id"]
    channel_id = user_id  # DM으로 결과 전송

    # 접수 알림
    client.chat_postMessage(
        channel=channel_id,
        text=f":hourglass_flowing_sand: *{skill}* 파이프라인을 시작했습니다.\n"
             f"컨텍스트: *{context}* / {quarter}\n"
             f"키워드: {keywords}\n"
             f"옵션: {'PPT ' if do_ppt else ''}{'Confluence' if do_confluence else ''}\n"
             f"완료되면 알림을 보내드릴게요.",
    )

    threading.Thread(
        target=run_okr_pipeline,
        kwargs=dict(
            context=context,
            quarter=quarter,
            keywords=keywords,
            do_ppt=do_ppt,
            do_confluence=do_confluence,
            parent_page_id=parent_page,
            user_id=user_id,
            channel_id=channel_id,
            slack_client=client,
        ),
        daemon=True,
    ).start()


if __name__ == "__main__":
    print("Nova Helper bot starting...")
    SocketModeHandler(app, os.environ["SLACK_APP_TOKEN"]).start()

