    )

    threading.Thread(
        target=run_okr_pipeline,
        kwargs=dict(
            context=context,
            quarter=quarter,
            keywords=keywords,
            do_ppt=do_ppt,
            do_confluence=do_confluence,
            parent_page_id=parent_page,
            user_id=user_id,
            channel_id=channel_id,
            slack_client=client,
        ),
        daemon=True,
    ).start()


